package com.icewright.generated.domain;

import org.junit.jupiter.api.Test;

import java.util.Map;
import java.util.Set;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * i18n 目录与语言回退的确定性单测：不依赖网络与 Redis。
 *
 * @author IceWright builder
 */
class I18nTest {

    @Test
    void catalogsCoverSameKeysInBothLanguages() {
        Set<String> zhKeys = I18n.languages();
        assertEquals(Set.of("en", "zh"), zhKeys);
        for (String key : new String[]{
            "pre_validator", "forbidden", "takeover", "transfer", "model_unavailable", "model_language"}) {
            assertTrue(I18n.t(key, "zh").length() > 0, key + " 中文目录缺失");
            assertTrue(I18n.t(key, "en").length() > 0, key + " 英文目录缺失");
        }
    }

    @Test
    void unknownLanguageFallsBackToDefault() {
        assertEquals(I18n.t("transfer", "zh"), I18n.t("transfer", "de"));
        assertEquals(I18n.t("transfer", "zh"), I18n.t("transfer", null));
        assertEquals("en", I18n.normalize(" EN "));
        assertEquals("en", I18n.normalize("EN"));
        assertEquals("zh", I18n.normalize("fr"));
    }

    @Test
    void ruleParamFormattedPerLanguage() {
        String zh = I18n.t("takeover", "zh", Map.of("rule", "R-0042"));
        String en = I18n.t("takeover", "en", Map.of("rule", "R-0042"));
        assertTrue(zh.contains("R-0042"), zh);
        assertTrue(en.contains("R-0042"), en);
        assertFalse(zh.contains("{rule}") || en.contains("{rule}"), "占位符应被替换");
    }

    @Test
    void modelLanguagePinDiffersPerLocale() {
        assertTrue(I18n.t("model_language", "zh").contains("中文"));
        assertTrue(I18n.t("model_language", "en").contains("English"));
    }
}
